#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "J/m³".parse::<EnergyDensityUnit>(),
        Ok(EnergyDensityUnit::JoulePerCubicMeter)
    );
    assert_eq!(
        format!("2.5 {}", "J/m³").parse::<EnergyDensity>(),
        Ok(EnergyDensity::new(
            2.5,
            EnergyDensityUnit::JoulePerCubicMeter
        ))
    );
    assert_eq!(
        "kJ/m³".parse::<EnergyDensityUnit>(),
        Ok(EnergyDensityUnit::KilojoulePerCubicMeter)
    );
    assert_eq!(
        format!("2.5 {}", "kJ/m³").parse::<EnergyDensity>(),
        Ok(EnergyDensity::new(
            2.5,
            EnergyDensityUnit::KilojoulePerCubicMeter
        ))
    );
    assert_eq!(
        "MJ/m³".parse::<EnergyDensityUnit>(),
        Ok(EnergyDensityUnit::MegajoulePerCubicMeter)
    );
    assert_eq!(
        format!("2.5 {}", "MJ/m³").parse::<EnergyDensity>(),
        Ok(EnergyDensity::new(
            2.5,
            EnergyDensityUnit::MegajoulePerCubicMeter
        ))
    );
    assert_eq!(
        "GJ/m³".parse::<EnergyDensityUnit>(),
        Ok(EnergyDensityUnit::GigajoulePerCubicMeter)
    );
    assert_eq!(
        format!("2.5 {}", "GJ/m³").parse::<EnergyDensity>(),
        Ok(EnergyDensity::new(
            2.5,
            EnergyDensityUnit::GigajoulePerCubicMeter
        ))
    );
    assert_eq!(
        "TJ/m³".parse::<EnergyDensityUnit>(),
        Ok(EnergyDensityUnit::TerajoulePerCubicMeter)
    );
    assert_eq!(
        format!("2.5 {}", "TJ/m³").parse::<EnergyDensity>(),
        Ok(EnergyDensity::new(
            2.5,
            EnergyDensityUnit::TerajoulePerCubicMeter
        ))
    );
    assert_eq!(
        "PJ/m³".parse::<EnergyDensityUnit>(),
        Ok(EnergyDensityUnit::PetajoulePerCubicMeter)
    );
    assert_eq!(
        format!("2.5 {}", "PJ/m³").parse::<EnergyDensity>(),
        Ok(EnergyDensity::new(
            2.5,
            EnergyDensityUnit::PetajoulePerCubicMeter
        ))
    );
    assert_eq!(
        "Wh/m³".parse::<EnergyDensityUnit>(),
        Ok(EnergyDensityUnit::WattHourPerCubicMeter)
    );
    assert_eq!(
        format!("2.5 {}", "Wh/m³").parse::<EnergyDensity>(),
        Ok(EnergyDensity::new(
            2.5,
            EnergyDensityUnit::WattHourPerCubicMeter
        ))
    );
    assert_eq!(
        "kWh/m³".parse::<EnergyDensityUnit>(),
        Ok(EnergyDensityUnit::KilowattHourPerCubicMeter)
    );
    assert_eq!(
        format!("2.5 {}", "kWh/m³").parse::<EnergyDensity>(),
        Ok(EnergyDensity::new(
            2.5,
            EnergyDensityUnit::KilowattHourPerCubicMeter
        ))
    );
    assert_eq!(
        "MWh/m³".parse::<EnergyDensityUnit>(),
        Ok(EnergyDensityUnit::MegawattHourPerCubicMeter)
    );
    assert_eq!(
        format!("2.5 {}", "MWh/m³").parse::<EnergyDensity>(),
        Ok(EnergyDensity::new(
            2.5,
            EnergyDensityUnit::MegawattHourPerCubicMeter
        ))
    );
    assert_eq!(
        "GWh/m³".parse::<EnergyDensityUnit>(),
        Ok(EnergyDensityUnit::GigawattHourPerCubicMeter)
    );
    assert_eq!(
        format!("2.5 {}", "GWh/m³").parse::<EnergyDensity>(),
        Ok(EnergyDensity::new(
            2.5,
            EnergyDensityUnit::GigawattHourPerCubicMeter
        ))
    );
    assert_eq!(
        "TWh/m³".parse::<EnergyDensityUnit>(),
        Ok(EnergyDensityUnit::TerawattHourPerCubicMeter)
    );
    assert_eq!(
        format!("2.5 {}", "TWh/m³").parse::<EnergyDensity>(),
        Ok(EnergyDensity::new(
            2.5,
            EnergyDensityUnit::TerawattHourPerCubicMeter
        ))
    );
    assert_eq!(
        "PWh/m³".parse::<EnergyDensityUnit>(),
        Ok(EnergyDensityUnit::PetawattHourPerCubicMeter)
    );
    assert_eq!(
        format!("2.5 {}", "PWh/m³").parse::<EnergyDensity>(),
        Ok(EnergyDensity::new(
            2.5,
            EnergyDensityUnit::PetawattHourPerCubicMeter
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<EnergyDensity>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = EnergyDensity::from_base(6.0);
    let b = EnergyDensity::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = EnergyDensity::<i64>::from_base(7);
    let b = EnergyDensity::<i64>::from_base(2);
    assert_eq!(a + b, EnergyDensity::from_base(9));
    assert_eq!(a % b, EnergyDensity::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<EnergyDensity<i64>>(),
        EnergyDensity::from_base(9)
    );
}
